// --- Issue #1: brick bounce -------------------------------------------------
//
// Brick grid geometry used below (makeBricks(1)): col 3 = x 244, col 4 = x 324,
// row 2 = y 104 (so the brick spans x [244, 316], y [104, 124]), row 3 = y 132.

function brickAt(bricks, x, y) {
  return bricks.find((b) => b.x === x && b.y === y);
}

// Ball ready to sweep into a brick: prev position is where the step started.
function incomingBall({ x, y, prevX, prevY, vx, vy }) {
  return { r: BALL_R, vx, vy, prevX, prevY, x, y };
}

test('brickHit: head-on bottom-face hit flips vy once and leaves vx alone', () => {
  const bricks = makeBricks(1);
  const brick = brickAt(bricks, 244, 104);
  const ball = incomingBall({ x: 244, y: 130, prevX: 244, prevY: 150, vx: 50, vy: -300 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 1);
  assert.ok(hits[0] === brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 300, 'vy must flip exactly (same magnitude)');
  assert.equal(ball.vx, 50, 'vx is left exactly as it was');
  assert.ok(ball.y >= brick.y + brick.h + BALL_R, 'ball pushed back out below the brick');
  assert.equal(collides(ball, brick), false, 'no residual overlap (no sticky bounce)');
});

test('brickHit: head-on top-face hit (ball coming down) flips vy up', () => {
  const bricks = makeBricks(1);
  const brick = brickAt(bricks, 244, 104);
  const ball = incomingBall({ x: 244, y: 100, prevX: 244, prevY: 70, vx: -25, vy: 300 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, -300);
  assert.equal(ball.vx, -25);
  assert.ok(ball.y <= brick.y - BALL_R, 'ball pushed back out above the brick');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: side hit flips vx and leaves vy alone', () => {
  const bricks = makeBricks(1);
  const brick = brickAt(bricks, 244, 104);
  const ball = incomingBall({ x: 322, y: 114, prevX: 330, prevY: 114, vx: -300, vy: 40 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 1);
  assert.ok(hits[0] === brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, 300);
  assert.equal(ball.vy, 40, 'vy is left exactly as it was');
  assert.ok(ball.x >= brick.x + brick.w + BALL_R, 'ball pushed back out to the right');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: corner hit (equal penetration) flips both components', () => {
  const bricks = makeBricks(1);
  const brick = brickAt(bricks, 244, 104);
  // Trajectory ends exactly on the brick's bottom-right corner (323, 131):
  // penetration is zero on both axes, so both components must flip.
  const ball = incomingBall({ x: 323, y: 131, prevX: 300, prevY: 160, vx: 200, vy: -200 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 1);
  assert.ok(hits[0] === brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, 200);
  assert.equal(collides(ball, brick), false);
});

test('brickHit: seam between two bricks breaks both but bounces exactly once', () => {
  const bricks = makeBricks(1);
  const left = brickAt(bricks, 244, 104);
  const right = brickAt(bricks, 324, 104);
  // Straight up through the 8 px gap at x = 320: the 14 px ball straddles both
  // bricks, but the bounce must be applied exactly once — a double flip would
  // cancel out (vy === -300) and the ball would keep going through.
  const ball = incomingBall({ x: 320, y: 130, prevX: 320, prevY: 160, vx: 0, vy: -300 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 2, 'both bricks at the seam die');
  assert.ok(hits.includes(left) && hits.includes(right));
  assert.equal(left.alive, false);
  assert.equal(right.alive, false);
  assert.equal(ball.vy, 300, 'flipped exactly once');
  assert.equal(ball.vx, 0);
