test('brickHit: tunnelling — a fast ball that never overlaps still hits (sweep)', () => {
  const bricks = makeBricks(1);
  const brick = brickAt(bricks, 244, 132); // row 3
  // 40 px per step is more than BRICK_H (20) + diameter (14) = 34: the ball
  // jumps over the whole brick and overlaps it at NEITHER endpoint.
  const prev = { x: 244, y: 160, r: BALL_R };
  const current = { x: 244, y: 120, r: BALL_R };
  assert.equal(collides(prev, brick), false, 'no overlap where the step starts');
  assert.equal(collides(current, brick), false, 'no overlap where the step ends');
  const ball = incomingBall({ x: current.x, y: current.y, prevX: prev.x, prevY: prev.y, vx: 0, vy: -710 });
  const hits = brickHit(ball, bricks);
  assert.equal(hits.length, 1);
  assert.ok(hits[0] === brick);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 710, 'the sweep catches the jump and flips vy');
  assert.ok(ball.y >= brick.y + brick.h + BALL_R);
  assert.equal(collides(ball, brick), false);
});

test('brickHit: push-out prevents a sticky re-hit on the next pass', () => {
  const bricks = makeBricks(1);
