  brickHit(ball, bricks);
  const after = { vx: ball.vx, vy: ball.vy, x: ball.x, y: ball.y };
  const hits = brickHit(ball, bricks); // one more pass, same state
  assert.equal(hits.length, 0, 'no re-hit, no double flip');
  assert.equal(ball.vx, after.vx);
  assert.equal(ball.vy, after.vy);
  assert.equal(ball.x, after.x);
  assert.equal(ball.y, after.y);
});

